check('electronic shared source flag hides kodeHat in summary and preview without mutating response',()=>{const original=JSON.stringify(electronicFixture),response={data:{data:electronicFixture}};const html=context.certificateDetailView(response,'Brankas/DetailSertipikatNew',{Dibagikan:true,DibagikanSampai:'2026-12-31<&'});assert.doesNotMatch(html,/ELECTRONIC-CODE-PRIVATE|kodeHat|<dt>Kode Sertipikat/);assert.match(html,/Dibagikan kepada saya sampai 2026-12-31&lt;&amp;/);assert.equal(JSON.stringify(electronicFixture),original);for(const Dibagikan of [false,null,undefined,'true'])assert.match(context.certificateDetailView(response,'Brankas/DetailSertipikatNew',{Dibagikan}),/<dt>Kode Sertipikat<\/dt><dd>ELECTRONIC-CODE-PRIVATE/)});
check('electronic location gates on top-level persilId and passes its untouched value to existing map control',()=>{const html=context.electronicCertificateLocation({...electronicFixture,persilId:' fixture-"<& ',persil:{persilId:'WRONG-ID',batasbidang:'WRONG-GEOMETRY'}});assert.match(html,/data-persil-id=" fixture-&quot;&lt;&amp; "/);assert.match(html,/Luas 150\.25 m2/);assert.doesNotMatch(html,/WRONG-/);const missing=context.electronicCertificateLocation({...electronicFixture,persilId:null});assert.match(missing,/Tidak ada data!/);assert.doesNotMatch(missing,/Lokasi elektronik|150\.25|certificate-map/);const blank=context.electronicCertificateLocation({...electronicFixture,persilId:''});assert.match(blank,/Lokasi elektronik fixture/);assert.doesNotMatch(blank,/data-action="certificate-map"/)});
check('electronic owner strings preserve source order, escaped text and records beyond preview limits',()=>{const listPemilik=Array.from({length:105},(_,i)=>`Electronic-owner-${i}`);listPemilik[1]='Owner <img src=x onerror=alert(1)>';const html=context.certificateDetailView({data:{...electronicFixture,listPemilik}},'Brankas/DetailSertipikatNew').split('<details class="json-details')[0];assert.match(html,/• Electronic-owner-104/);assert.match(html,/Owner &lt;img src=x onerror=alert\(1\)&gt;/);assert.doesNotMatch(html,/<img/);assert.ok(html.indexOf('Electronic-owner-0')<html.indexOf('Owner &lt;img'));assert.ok(html.indexOf('Electronic-owner-103')<html.indexOf('Electronic-owner-104'));const empty=context.certificateDetailView({data:{...electronicFixture,listPemilik:[]}},'Brankas/DetailSertipikatNew');const ownerSection=empty.slice(empty.indexOf('<h3>Pemilik</h3>'),empty.indexOf('<h3>Catatan Pendaftaran</h3>'));assert.doesNotMatch(ownerSection,/Tidak ada/)});
check('electronic notes show only kolom1, skip only all-null records and keep null kolom1 blank',()=>{const html=context.certificateDetailView({data:electronicFixture},'Brankas/DetailSertipikatNew');const visible=html.split('<details class="json-details')[0];assert.equal((visible.match(/class="certificate-note"/g)||[]).length,3);assert.match(visible,/Electronic first\nNext line/);assert.match(visible,/class="certificate-note"><p><\/p>/);assert.doesNotMatch(visible,/HIDDEN-NATIVE-COLUMN|COLUMN-[234]-ONLY|<script|<br/i);assert.match(visible,/Electronic last &lt;script&gt;alert\(1\)&lt;\/script&gt;/);for(const value of ['COLUMN-2-ONLY','COLUMN-3-ONLY','COLUMN-4-ONLY'])assert.ok(html.includes(value));assert.match(context.electronicCertificateNote({kolom1:null,kolom2:'not null'}),/<p><\/p>/)});
check('electronic note empty input differs from a nonempty list of all-null records',()=>{for(const catatan of [null,[]]){const html=context.certificateDetailView({data:{...electronicFixture,catatan}},'Brankas/DetailSertipikatNew').split('<details class="json-details')[0];assert.match(html,/Catatan Pendaftaran<\/h3>[\s\S]*Tidak ada data!/)}const html=context.certificateDetailView({data:{...electronicFixture,catatan:[{kolom1:null,kolom2:null,kolom3:null,kolom4:null}]}},'Brankas/DetailSertipikatNew').split('<details class="json-details')[0];const section=html.slice(html.indexOf('<h3>Catatan Pendaftaran</h3>'));assert.doesNotMatch(section,/Tidak ada data|certificate-note|certificate-record/);const emptyString=context.certificateDetailView({data:{...electronicFixture,catatan:[{kolom1:'',kolom2:null,kolom3:null,kolom4:null}]}},'Brankas/DetailSertipikatNew').split('<details class="json-details')[0];assert.match(emptyString,/class="certificate-note"><p><\/p>/)});
check('electronic complete note preview retains hidden columns past hundredth row without changing source',()=>{const catatan=Array.from({length:105},(_,i)=>({kolom1:`VISIBLE-NOTE-${i}`,kolom2:`RAW-COLUMN-TWO-${i}`,kolom3:null,kolom4:i===104?'LAST-RAW-FOUR-<&':null}));const original=JSON.stringify(catatan),html=context.certificateDetailView({data:{...electronicFixture,catatan}},'Brankas/DetailSertipikatNew');const visible=html.split('<details class="json-details')[0],raw=html.slice(html.indexOf('<summary>Seluruh kolom catatan</summary>'),html.indexOf('<summary>Pratinjau respons JSON</summary>'));assert.equal((visible.match(/class="certificate-note"/g)||[]).length,105);assert.match(visible,/VISIBLE-NOTE-104/);assert.doesNotMatch(visible,/RAW-COLUMN-TWO|LAST-RAW/);assert.match(raw,/RAW-COLUMN-TWO-104/);assert.match(raw,/LAST-RAW-FOUR-&lt;&amp;/);assert.equal(JSON.stringify(catatan),original)});
